def _install_modules() -> None:
    for name in INSTALL_ORDER:
        source = SOURCES[name]
        module = types.ModuleType(name)
        module.__file__ = f"<xi_portable:{name}>"
        sys.modules[name] = module
        exec(compile(source, module.__file__, "exec"), module.__dict__)


def self_check() -> dict[str, Any]:
    if sys.version_info[:2] < MIN_PYTHON:
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": f"Python {MIN_PYTHON[0]}.{MIN_PYTHON[1]}+ required",
        }
    try:
        _install_modules()
        from adapter import run_decision
        from step2_reconcile import reconcile_step2
        from model_bet_accounting import compile_fixture_accounting
    except Exception as exc:
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": f"{type(exc).__name__}: {exc}",
        }

    if not all(callable(x) for x in (run_decision, reconcile_step2, compile_fixture_accounting)):
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": "required C+C2 Step-2/accounting callables are missing",
        }

    return {
        "ok": True,
        "status": "XI PORTABLE RUNTIME: PASS",
        "active_models": ["c", "c2"],
        "python_version": ".".join(map(str, sys.version_info[:3])),
        "embedded_modules": list(INSTALL_ORDER),
        "source_blob_sha": SOURCE_BLOB_SHA,
    }


def _load(path: str) -> dict[str, Any]:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _pair_epoch_signature(payload: dict[str, Any]) -> str:
    match = payload.get("match")
    context = payload.get("context")
    if not isinstance(match, dict):
        raise ValueError("C+C2 pair requires match object")
    if not isinstance(context, dict):
        raise ValueError("C+C2 pair requires context object")
    frozen = {
        "match": {key: match.get(key) for key in COMMON_MATCH_FIELDS},
        "context": {key: context.get(key) for key in COMMON_CONTEXT_FIELDS},
    }
    return json.dumps(frozen, sort_keys=True, separators=(",", ":"))


def run_football_pair_files(c: str, c2: str) -> dict[str, Any]:
    """Run C/C2 football hypotheses with no bookmaker quote requirements."""
    _install_modules()
    from adapter import run_football_assessment
    payloads = {"c": _load(c), "c2": _load(c2)}
    signatures = set()
    for model in ("c", "c2"):
        payload = payloads[model]
        if str(payload.get("model", "")).lower() != model:
            raise ValueError(f"football pair expected model={model}")
        if payload.get("stage") != "football_assessment":
            raise ValueError("football-pair needs stage=football_assessment")
        match, ctx = payload.get("match"), payload.get("context")
        if not isinstance(match, dict) or not isinstance(ctx, dict):
            raise ValueError("football pair requires match and context objects")
        eid = payload.get("evidence_epoch_id")
        if not isinstance(eid, str) or not eid.strip():
            raise ValueError("football pair requires evidence_epoch_id")
        at = ctx.get("assessment_at_utc")
        if not isinstance(at, str) or not at.strip():
            raise ValueError("football pair requires assessment_at_utc")
        signatures.add(json.dumps({
            "match_id": match.get("match_id"),
            "kickoff_ict": match.get("kickoff_ict"),
            "evidence_epoch_id": eid, "assessment_at_utc": at,
            "fixture_status": ctx.get("fixture_status"),
            "score": ctx.get("score"), "match_minute": ctx.get("match_minute"),
            "material_event_since_frozen": ctx.get("material_event_since_frozen"),
        }, sort_keys=True))
    if len(signatures) != 1:
        raise ValueError("C+C2 football pair evidence epoch/status/score mismatch")
    results = {m: run_football_assessment(payloads[m]) for m in ("c", "c2")}
    return {
        "engine_execution_status": "EXECUTED_C_C2_FOOTBALL_ONLY",
        "models_executed": ["c", "c2"], "quotes_required": False,
        "quote_research_required": False, "model_bets_created": False,
        "model_accounting_status": "NONE", "results": results,
    }


def run_pair_files(c: str, c2: str) -> dict[str, Any]:
    """Execute active C+C2 validators atomically from one frozen evidence epoch."""
    _install_modules()
    from adapter import run_decision

    payloads = {"c": _load(c), "c2": _load(c2)}
    signatures = set()

    for model in ("c", "c2"):
        payload = payloads[model]
        actual = str(payload.get("model", "")).lower()
        if actual != model:
            raise ValueError(
                f"pair payload mismatch: expected model={model}, got {actual or '<missing>'}"
            )
        if payload.get("stage") != "decision":
            raise ValueError(f"pair payload model={model} must use stage=decision")
        signatures.add(_pair_epoch_signature(payload))

    if len(signatures) != 1:
        raise ValueError(
            "C+C2 pair must share the same frozen common evidence epoch"
        )

    results = {model: run_decision(payloads[model]) for model in ("c", "c2")}

    return {
        "engine_execution_status": "EXECUTED_C_C2_PAIR",
        "models_executed": ["c", "c2"],
        "results": results,
    }


def run_reconcile_file(path: str) -> dict[str, Any]:
    _install_modules()
    from step2_reconcile import reconcile_step2
    return reconcile_step2(_load(path))


def run_accounting_file(path: str) -> dict[str, Any]:
    _install_modules()
    from model_bet_accounting import compile_fixture_accounting
    return compile_fixture_accounting(_load(path))



def _screenshot_time(value: Any, field: str) -> datetime:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be an ISO timestamp with timezone")
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"{field} must be an ISO timestamp with timezone") from exc
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError(f"{field} must include a timezone")
    return dt


def assess_user_screenshot(
    screenshot: dict[str, Any],
    c_football: dict[str, Any],
    c2_football: dict[str, Any],
    football: dict[str, Any],
    priced_inputs: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Evaluate only the user's observed quote. Never fetch or re-time a price.

    Indicative actions use the unchanged adapter decision engine with the
    quote-revalidation gate simulated IN MEMORY for price comparison only.
    A screenshot can never independently prove a still-open executable offer,
    so screenshot-only mode can never authorize exposure or publication.
    """
    if not isinstance(screenshot, dict):
        raise ValueError("screenshot evidence must be an object")
    if screenshot.get("evidence_mode") != "USER_SCREENSHOT_ONLY" or screenshot.get("source") != "USER_SCREENSHOT":
        raise ValueError("only source=USER_SCREENSHOT, evidence_mode=USER_SCREENSHOT_ONLY is accepted")
    capture_reference = screenshot.get("capture_reference")
    if not isinstance(capture_reference, str) or not capture_reference.strip():
        raise ValueError("original screenshot capture_reference required")
    match_id = football["results"]["c"]["match_id"]
    if screenshot.get("match_id") != match_id:
        raise ValueError("screenshot match_id differs from C/C2 football fixture")
    quote = screenshot.get("quote")
    if not isinstance(quote, dict):
        raise ValueError("screenshot must show exact quote line and odds")
    line, odds = quote.get("line"), quote.get("odds")
    if (type(line) not in (int, float) or type(odds) not in (int, float)
            or not math.isfinite(line) or not math.isfinite(odds)
            or line < 0 or abs(line * 4 - round(line * 4)) > 1e-8
            or odds <= 1):
        raise ValueError("invalid screenshot Asian quarter-goal line or decimal odds")
    fixture = c_football["context"].get("fixture_status")
    if screenshot.get("fixture_status") != fixture or c2_football["context"].get("fixture_status") != fixture:
        raise ValueError("screenshot fixture status conflicts with paired football evidence")
    assessment_time = _screenshot_time(c_football["context"]["assessment_at_utc"], "assessment_at_utc")
    if _screenshot_time(c2_football["context"]["assessment_at_utc"], "assessment_at_utc") != assessment_time:
        raise ValueError("C/C2 assessment times differ")
    captured = screenshot.get("observed_at_utc")
    captured_time = _screenshot_time(captured, "observed_at_utc") if captured is not None else None
    if captured_time is not None and captured_time > assessment_time:
        raise ValueError("screenshot observation cannot be later than assessment epoch")
    if fixture in {"STARTED", "HALFTIME"}:
        if (screenshot.get("score") is None or screenshot.get("match_minute") is None
                or screenshot["score"] != c_football["context"].get("score")
                or screenshot["match_minute"] != c_football["context"].get("match_minute")):
            raise ValueError("live screenshot score/minute must match actual C/C2 football epoch")
    elif fixture == "PREMATCH_CONFIRMED":
        if screenshot.get("score") is not None or screenshot.get("match_minute") is not None:
            raise ValueError("prematch screenshot cannot inherit a live score/minute")
    evidence = {
        "price_evidence_mode": "USER_SCREENSHOT_ONLY",
        "source": "USER_SCREENSHOT",
        "capture_reference": capture_reference,
        "match_id": match_id,
        "bookmaker": screenshot.get("bookmaker"),
        "quote": {"line": line, "odds": odds},
        "observed_at_utc": captured,
        "assessment_at_utc": c_football["context"]["assessment_at_utc"],
        "observation_age_seconds": (assessment_time - captured_time).total_seconds() if captured_time else None,
        "fixture_status": fixture,
        "score": screenshot.get("score"),
        "match_minute": screenshot.get("match_minute"),
        "external_price_searches": 0,
        "replacement_quotes": 0,
    }
    limitations = []
    if captured_time is None:
        limitations.append("SCREENSHOT_CAPTURE_TIME_UNKNOWN")
    elif captured_time != assessment_time:
        limitations.append("SCREENSHOT_OBSERVATION_NOT_SAME_AS_ASSESSMENT_EPOCH")
    if fixture != "PREMATCH_CONFIRMED":
        limitations.append("LIVE_SCREENSHOT_NOT_EXECUTABLE_BY_PREMATCH_ENGINE")
    model_verdicts = {}
    for model in ("c", "c2"):
        funded = football["results"][model]["frozen_supported_line"]
        model_verdicts[model] = {
            "supported_line": funded,
            "snapshot_line_relation": ("ABOVE_SUPPORTED_BURDEN" if line > funded else
                                       "AT_SUPPORTED_BURDEN" if line == funded else
                                       "BELOW_SUPPORTED_BURDEN"),
            "conditional_action": "NOT_EVALUATED_MISSING_PRICED_MODEL_CONTEXT",
            "bet_authorized": False,
        }
    base = {
        "ok": False, "status": "SCREENSHOT_PRICE_ASSESSED_CONDITIONAL",
        "evidence": evidence, "models": model_verdicts,
        "limitations": limitations,
        "bet_authorized": False, "model_bets_created": False,
        "priced_publication_authorized": False,
        "quote_research_required": False,
    }
    if fixture != "PREMATCH_CONFIRMED":
        for v in model_verdicts.values():
            v["conditional_action"] = "LIVE_PRICE_BURDEN_COMPARISON_ONLY"
            v["live_price_assessment"] = "LIVE_ENGINE_AUTHORIZATION_NOT_EXECUTED"
        limitations.append("LIVE_SCREENSHOT_REQUIRES_LIVE_ENGINE_FOR_ACTION")
        return base
    if priced_inputs is None:
        limitations.append("INDEPENDENT_C_C2_PRICED_CONTEXT_NOT_PROVIDED")
        return base
    for model, f_input in (("c", c_football), ("c2", c2_football)):
        p = priced_inputs[model]
        if (p.get("stage") != "decision" or p.get("model") != model
                or p.get("match", {}).get("match_id") != match_id
                or p.get("evidence_epoch_id") != f_input["evidence_epoch_id"]):
            raise ValueError(f"{model}: screenshot price payload must match football model/match/epoch")
        if p["match"].get("supported_line") != football["results"][model]["frozen_supported_line"]:
            raise ValueError(f"{model}: priced supported burden differs from independent football model")
        context = p.get("context")
        if not isinstance(context, dict) or context.get("fixture_status") != fixture:
            raise ValueError(f"{model}: priced context fixture state mismatch")
        existing_quote = context.get("quote")
        if existing_quote is not None and existing_quote != {"line": line, "odds": odds}:
            raise ValueError(f"{model}: external or replacement quote differs from user screenshot")
    if _pair_epoch_signature(priced_inputs["c"]) != _pair_epoch_signature(priced_inputs["c2"]):
        raise ValueError("screenshot C/C2 priced decision epochs do not reconcile")
    _install_modules()
    from adapter import run_decision
    # No part of this temporary hypothetical validation is persisted to a
    # betting ledger, returned as an executable recommendation, or used to
    # claim an actually revalidated price.
    for model in ("c", "c2"):
        p = copy.deepcopy(priced_inputs[model])
        p["context"]["quote"] = {"line": line, "odds": odds}
        p["context"]["quote_revalidated"] = True
        try:
            decision = run_decision(p)
            model_verdicts[model].update({
                "conditional_action": "ACT" if decision["action"] == "BET" else decision["action"],
                "price_engine_action": decision["action"],
                "price_engine_reason": decision["reason"],
                "wait_target_line": decision["wait_target_line"],
                "wait_min_odds": decision["wait_min_odds"],
                "indicative_only": True,
            })
        except Exception as exc:
            model_verdicts[model]["conditional_action"] = "NOT_EVALUATED_RULES_INCOMPLETE"
            model_verdicts[model]["price_rule_limitation"] = str(exc)
    # A screenshot is a historical display observation, NOT independent
    # proof that an executable offer was still open when model execution
    # finished. Neither a caller-supplied boolean nor matching timestamps
    # authorize an actual C bet. The unchanged strict price engine above
    # provides conditional ACT/WAIT/PASS only.
    limitations.append("SCREENSHOT_CANNOT_INDEPENDENTLY_PROVE_EXECUTABLE_OFFER")
    if screenshot.get("open_offer_verified_in_screenshot") is True:
        limitations.append("OPEN_OFFER_FLAG_NOT_INDEPENDENT_EXECUTION_EVIDENCE")
    limitations.append("SCREENSHOT_PRICE_NOT_VERIFIED_EXECUTABLE_AT_ASSESSMENT")
    return base


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Portable Football /xi C+C2 deterministic runtime"
    )
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("self-check")
    # Short user-stage names. Historical names retained for old scripts.
    one = sub.add_parser("xi")
    one.add_argument("--c", required=True)
    one.add_argument("--c2", required=True)
    # New /xi one-turn contract: --c/--c2 are the independent football
    # hypotheses. Priced offers are optional and never replace football.
    one.add_argument("--price-c")
    one.add_argument("--price-c2")
    one.add_argument("--screenshot-quote", help="USER_SCREENSHOT_ONLY JSON evidence; never search replacement odds")
    pair = sub.add_parser("pair")
    pair.add_argument("--c", required=True)
    pair.add_argument("--c2", required=True)
    price = sub.add_parser("bet-check")
    price.add_argument("--c", required=True)
    price.add_argument("--c2", required=True)
    football_pair = sub.add_parser("football-pair")
    football_pair.add_argument("--c", required=True)
    football_pair.add_argument("--c2", required=True)
    assess = sub.add_parser("assess")
    assess.add_argument("--c", required=True)
    assess.add_argument("--c2", required=True)
    reconcile = sub.add_parser("reconcile")
    reconcile.add_argument("--input", required=True)
    accounting = sub.add_parser("accounting")
    accounting.add_argument("--input", required=True)
    args = parser.parse_args()

    try:
        if args.command == "self-check":
            result = self_check()
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0 if result.get("ok") else 2
        if args.command == "xi":
            c_input, c2_input = _load(args.c), _load(args.c2)
            mode1, mode2 = c_input.get("stage"), c2_input.get("stage")
            if mode1 != mode2:
                raise ValueError("C+C2 must use the same /xi mode and current match epoch")
            if bool(args.price_c) != bool(args.price_c2):
                raise ValueError("both C and C2 separate price inputs are required")
            if args.screenshot_quote and mode1 != "football_assessment":
                raise ValueError("screenshot-only price mode requires independently executed C+C2 football inputs")
            if mode1 == "football_assessment":
                # Execute independently frozen C/C2 football FIRST. A
                # rejected/stale bookmaker price may never erase it.
                result = run_football_pair_files(args.c, args.c2)
                if args.screenshot_quote:
                    try:
                        priced_inputs = ({"c": _load(args.price_c), "c2": _load(args.price_c2)} if args.price_c else None)
                        price = assess_user_screenshot(_load(args.screenshot_quote), c_input, c2_input, result, priced_inputs)
                        mode = ("FOOTBALL_AND_SCREENSHOT_PRICE_CHECK" if price["ok"]
                                else "FOOTBALL_ASSESSED_SCREENSHOT_PRICE_LIMITED")
                    except Exception as exc:
                        price = {"ok": False, "status": "PRICE_CHECK_BLOCKED",
                                 "price_evidence_mode": "USER_SCREENSHOT_ONLY",
                                 "failure_class": "SCREENSHOT_EVIDENCE_OR_PRICE_CONTRACT",
                                 "reason": str(exc), "bet_authorized": False,
                                 "external_price_searches": 0, "replacement_quotes": 0}
                        mode = "FOOTBALL_ASSESSED_PRICE_CHECK_BLOCKED"
                    output = {"ok": True, "xi_mode": mode, **result, "price_check": price}
                elif not args.price_c:
                    output = {"ok": True, "xi_mode": "FOOTBALL_ASSESSMENT", **result}
                else:
                    try:
                        price_c, price_c2 = _load(args.price_c), _load(args.price_c2)
                        if price_c.get("stage") != "decision" or price_c2.get("stage") != "decision":
                            raise ValueError("price subdecision must use independent stage=decision pair")
                        if (price_c.get("match",{}).get("match_id") != result["results"]["c"]["match_id"]
                                or price_c2.get("match",{}).get("match_id") != result["results"]["c2"]["match_id"]
                                or price_c.get("evidence_epoch_id") != c_input.get("evidence_epoch_id")
                                or price_c2.get("evidence_epoch_id") != c2_input.get("evidence_epoch_id")):
                            raise ValueError("price subdecision cannot borrow another match/epoch")
                        if (c_input["context"].get("fixture_status") != "PREMATCH_CONFIRMED"
                                or c2_input["context"].get("fixture_status") != "PREMATCH_CONFIRMED"):
                            raise ValueError("STARTED/HALFTIME: prematch priced pair forbidden; route current live bet authorization separately")
                        priced = run_pair_files(args.price_c, args.price_c2)
                        price = {"ok": True, "status": "PRICE_CHECK_EXECUTED",
                                 "receipt": priced}
                        mode = "FOOTBALL_AND_PRICE_CHECK"
                    except Exception as exc:
                        # A price check can be incomplete, including because
                        # fixture has started; the paired football assessment
                        # still COMPLETED and remains displayed. No pretend bet.
                        price = {"ok": False, "status": "PRICE_CHECK_BLOCKED",
                                 "failure_class": "PRICE_EXECUTION_OR_CONTRACT",
                                 "reason": str(exc),
                                 "bet_authorized": False}
                        mode = "FOOTBALL_ASSESSED_PRICE_CHECK_BLOCKED"
                    output = {"ok": True, "xi_mode": mode, **result,
                              "price_check": price}
            elif mode1 == "decision":
                if args.price_c:
                    raise ValueError("priced-only legacy inputs cannot also specify --price-c/--price-c2")
                # Backward compatibility with old Step2 callers. Unlike the
                # new football-first path this mode cannot claim football
                # fallback without two genuine football_assessment inputs.
                result = run_pair_files(args.c, args.c2)
                output = {"ok": True, "xi_mode": "LEGACY_PREMATCH_PRICE_CHECK",
                          "football_first_executed": False, **result}
            else:
                raise ValueError("/xi expects stage=football_assessment or stage=decision")
            print(json.dumps(output, indent=2, sort_keys=True))
            return 0
        if args.command in {"pair", "bet-check"}:
            result = run_pair_files(args.c, args.c2)
            print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
            return 0
        if args.command in {"football-pair", "assess"}:
            result = run_football_pair_files(args.c, args.c2)
            print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
            return 0
        if args.command == "reconcile":
            result = run_reconcile_file(args.input)
            print(json.dumps({"ok": True, "step2_reconciliation_status": "PASS", **result}, indent=2, sort_keys=True))
            return 0
        result = run_accounting_file(args.input)
        print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
        return 0
    except Exception as exc:
        error_type = type(exc).__name__
        contract_types = {
            "ContractError",
            "Step2ReconciliationError",
            "ModelBetAccountingError",
            "ValueError",
            "KeyError",
            "JSONDecodeError",
        }
        is_contract = error_type in contract_types
        print(json.dumps({
            "ok": False,
            "status": "XI ENGINE CONTRACT REJECTED" if is_contract else "XI PORTABLE RUNTIME: EXECUTION FAILED",
            "failure_class": "PAYLOAD_OR_MODEL_CONTRACT" if is_contract else "PYTHON_OR_RUNTIME",
            "error_type": error_type,
            "error": str(exc),
        }, indent=2, sort_keys=True), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
